import java.util.*;class OutOfStockException extends Exception{int shortfall;OutOfStockException(int n){super("Shortfall: "+n);shortfall=n;}}class InvalidQuantityException extends Exception{InvalidQuantityException(){super("Quantity must be positive");}}class Warehouse{int stock=5;void issue(String item,int q)throws OutOfStockException,InvalidQuantityException{if(q<=0)throw new InvalidQuantityException();if(q>stock)throw new OutOfStockException(q-stock);stock-=q;System.out.println("Issued "+q+" "+item);}}public class WarehouseDemo{public static void main(String[]x){Warehouse w=new Warehouse();for(int q:new int[]{2,0,8,1})try{w.issue("pen",q);}catch(Exception e){System.out.println(e.getMessage());}System.out.println("Stock="+w.stock);}}
